using NUnit.Framework;

[TestFixture]
public class FactorialTests
{
    [TestCase(0, 1L)]
    [TestCase(1, 1L)]
    [TestCase(5, 120L)]
    public void Factorial_ReturnsExpected(int n, long expected)
    {
        Assert.That(Factorial(n), Is.EqualTo(expected));
    }

    private long Factorial(int n)
    {
        long result = 1;
        for (int i = 2; i <= n; i++)
            result *= i;
        return result;
    }
}
